  {sec:"Temperament","fn":"TMP_SAN","t":"Your approach to fun and leisure is:","type":"mc","choices":[{l:"A",t:"Spontaneous and social \u2014 the more energy in the room the better","s":7},{l:"B",t:"Solitary and focused \u2014 I recharge through quiet activity","s":2},{l:"C",t:"With the people I care about \u2014 fun is relational for me","s":4},{l:"D",t:"Comfortable and low-key \u2014 peace and quiet are genuinely enjoyable","s":3}]},
  {sec:"Temperament","fn":"TMP_PHL","t":"When there's conflict or urgency around you, you tend to:","type":"mc","choices":[{l:"A",t:"Stay calm and composed \u2014 I don't get swept up in others' urgency","s":7},{l:"B",t:"Get activated and decisive \u2014 I move into action mode","s":2},{l:"C",t:"Try to calm everyone down and find a resolution","s":3},{l:"D",t:"Analyze carefully before responding \u2014 urgency doesn't change my process","s":4}]},
  {sec:"Temperament","fn":"TMP_PHL","t":"Change in your environment or routine feels:","type":"mc","choices":[{l:"A",t:"Fine \u2014 I adapt easily and don't need things to stay the same","s":7},{l:"B",t:"Interesting when I initiate it, uncomfortable when imposed on me","s":3},{l:"C",t:"Something to navigate together with the people around me","s":4},{l:"D",t:"Disruptive \u2014 consistency and stability support my best work","s":2}]}
